head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > E > oninputinvalid]<br/>컴포넌트에서 입력을 허용하지 않은 문자가 입력되었을때 발생합니다.",
    "validation" : [
        "입력된 문자가 datatype, allowChar, ignoreChar 등의 속성에서 입력이 허용된 문자가 아닌 경우 이벤트가 발생합니다.",
        "fireEventOnInvalid=true 인 경우만 발생하는 이벤트입니다.",
        "info 파라미터로 입력된 문자에 대한 정보를 가진 객체가 전달됩니다.",
        "info 객체의 callerId 속성으로 이벤트가 발생한 컴포넌트의 렌더링 ID 값을 갖습니다.",
        "info 객체의 type 속성으로 입력된 문자가 검증을 통과하지 못한 원인이 되는 속성의 이름을 갖습니다.",
        "info 객체의 value 속성으로 type 으로 전달된 속성에 설정된 값을 갖습니다.",
        "info 객체의 detail 속성으로 입력된 문자가 검증을 통과하지 못한 이유에 대한 추가정보를 갖습니다.",
        "datatype 속성이 number 또는 bigDecimal 이고 displayFormat 이 설정되지 않은 경우 이벤트 객체의 type 속성은 'allowChar' 값을 갖습니다.",
        "allowChar 속성이 설정된 상태에서 컴포넌트의 포커스가 해제될때와 Tab 키가 입력될때는 이벤트가 발생하지 않으나 Enter 키 입력 시 이벤트가 발생합니다.",
        "editFormat 속성의 마스크 문자로 입력이 허용되지 않은 경우엔 이벤트가 발생하지 않습니다.",
        "한글과 같은 다국어 문자를 입력하는 경우와 입력값을 붙여넣기 하는 경우엔 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.target_oninputinvalid = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target_oninputinvalid 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.callerId  : " + info.callerId);
    wf_body_bottom.getObj("scwin").setReturnValue("info.type   : " + info.type);
    wf_body_bottom.getObj("scwin").setReturnValue("info.value   : " + info.value);
    wf_body_bottom.getObj("scwin").setReturnValue("info.detail   : " + info.detail);
};
